package com.example.madfinalproject;
import android.content.Intent; import android.os.Bundle; import android.view.View; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class FoundationFlowActivity extends AppCompatActivity {
 private String screen; private TextView title,heroTitle,heroSub,progress,section,row1,row2,row3,row4,row5,tip; private Button primary,secondary;
 protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_foundation_flow);screen=getIntent().getStringExtra("screen");bind();render();}
 private void bind(){title=findViewById(R.id.title);heroTitle=findViewById(R.id.heroTitle);heroSub=findViewById(R.id.heroSub);progress=findViewById(R.id.progressText);section=findViewById(R.id.sectionTitle);row1=findViewById(R.id.row1);row2=findViewById(R.id.row2);row3=findViewById(R.id.row3);row4=findViewById(R.id.row4);row5=findViewById(R.id.row5);tip=findViewById(R.id.tip);primary=findViewById(R.id.btnPrimary);secondary=findViewById(R.id.btnSecondary);findViewById(R.id.btnBack).setOnClickListener(v->finish());primary.setOnClickListener(v->next());secondary.setOnClickListener(v->finish());row1.setOnClickListener(v->{if("parts".equals(screen))open("lesson");else if("words".equals(screen))open("card");});}
 private void set(String t,String h,String sub,String pr,String sec,String... rows){title.setText(t);heroTitle.setText(h);heroSub.setText(sub);progress.setText(pr);section.setText(sec);TextView[] all={row1,row2,row3,row4,row5};for(int i=0;i<all.length;i++){if(i<rows.length){all[i].setVisibility(View.VISIBLE);all[i].setText(rows[i]);}else all[i].setVisibility(View.GONE);}}
 private void render(){if(screen==null)screen="grammar";switch(screen){case"grammar":set("Grammar","Grammar","Learn the rules and build strong sentences.","40%     8 / 20 Lessons Completed","Grammar Topics","1.  Parts of Speech                         80%  ›","2.  Tenses                                      30%  ›","3.  Subject & Verb Agreement             0%  ›","4.  Articles                                      0%  ›","5.  Prepositions                                0%  ›");primary.setText("Open Parts of Speech  →");break;case"parts":set("Parts of Speech","1. Parts of Speech","Learn about nouns, pronouns, verbs, adjectives, adverbs and more.","60%     3 / 5 Lessons Completed","Lessons","1     What is a Noun?                         ✓","2     Types of Nouns                            ✓","3     Pronouns                                    ✓","4     Verbs                                         ▶","5     Adjectives & Adverbs                   🔒");primary.setText("Start Quick Test");tip.setText("Quick Test • Test your understanding of this topic");break;case"lesson":set("What is a Noun?","▶  What is a Noun?","Video Lesson  •  02:15 / 10:00","Lesson     Examples     Notes","Lesson Content","A noun is a word that names a person, place, thing, or idea.","• Person: Ali, Teacher, Doctor","• Place: School, Lahore, Park","• Thing: Book, Pen, Computer","• Idea: Happiness, Freedom, Love");primary.setText("Next  →");secondary.setText("← Previous");tip.setText("Tip: Nouns can be singular (book) or plural (books).");break;case"question":set("Practice Question","Question 2 of 10","⏱ 08:45","Progress  20%","Which of the following is a noun?","A     Quickly                         ○","B     Beautiful                       ○","C     Happiness                    ●","D     Run                                ○");primary.setText("Start Question");tip.setText("Explanation: Happiness is a noun. It is a word that names an idea or feeling.");break;case"vocabulary":set("Vocabulary","Vocabulary","Learn new words and expand your vocabulary.","35%     6 / 18 Lessons Completed","Categories","1.  Basic Words                              40%  ›","2.  Everyday Words                         20%  ›","3.  Academic Words                           0%  ›");primary.setText("Open Basic Words  →");break;case"words":set("Basic Words","1. Basic Words","Learn essential words for daily life.","40%     2 / 6 Lessons Completed","Lessons","1     Common Nouns                          ✓","2     Common Verbs                           ✓","3     Common Adjectives                    ▶","4     Family Words                              🔒","5     Food Words                                🔒");primary.setText("Open Flashcards  →");break;case"card":set("Common Nouns","📗","book","3 / 15","A written or printed work on pages.","Example: I am reading an interesting book.");primary.setText("I Know");secondary.setText("I Don't Know");tip.setText("🔊 Tap the speaker to hear pronunciation");break;case"quiz":set("Daily Quiz","🏆 Daily Quiz","Test your knowledge daily!","10 Questions        10:00 Time        +10 Points","Topics","🌿 Grammar","🧡 Vocabulary","📖 Reading","▦ Mixed");primary.setText("Start Quiz");break;case"progress":set("My Progress","35%  Overall Progress","Great! Keep going.","25 / 72 Lessons     72% Avg. Score     12h 30m","Weekly Activity","Mon  ▃  45m","Tue   ▆  70m","Wed ▄  40m","Thu  ▅  55m","Fri    ▆  65m");primary.setText("View Detailed Analysis");tip.setText("Topics Overview  •  Grammar 40%  •  Vocabulary 35%  •  Reading 30%");break;}}
 private void next(){switch(screen){case"grammar":open("parts");break;case"parts":open("question");break;case"lesson":open("question");break;case"vocabulary":open("words");break;case"words":open("card");break;case"card":open("card");break;case"quiz":open("question");break;default:Toast.makeText(this,"Progress updated",Toast.LENGTH_SHORT).show();}}
 private void open(String s){startActivity(new Intent(this,FoundationFlowActivity.class).putExtra("screen",s));}
}
